head.script:
// [FAIL] mapchart 는 setDisabled(true) / setReadOnly(true) 상태에서도
//        지도 클릭 시 하위 지도로 이동(레벨 변경)되고 onmapclick 이벤트도 그대로 발생한다.

// onaftermapchange 는 최초 렌더 시에도 1회 발생하므로, 지도별로 그 1회만 결과창에서 제외한다.
scwin.rendered = {
    "map_disabled" : false,
    "map_readonly" : false
};



scwin.onpageload = function () {
    // 결함 조건 설정
    map_disabled.setDisabled(true);
    map_readonly.setReadOnly(true);
};



// [A] setDisabled(true)
scwin.map_disabled_onmapclick = function (info) {
    scwin.setReturnValue("[A] onmapclick : " + info.name);
};

scwin.map_disabled_onaftermapchange = function () {
    if (!scwin.rendered["map_disabled"]) {
        scwin.rendered["map_disabled"] = true;
        return;
    }

    scwin.setReturnValue("[A] 지도 변경 : " + map_disabled.getCurrentMap());
};



// [B] setReadOnly(true)
scwin.map_readonly_onmapclick = function (info) {
    scwin.setReturnValue("[B] onmapclick : " + info.name);
};

scwin.map_readonly_onaftermapchange = function () {
    if (!scwin.rendered["map_readonly"]) {
        scwin.rendered["map_readonly"] = true;
        return;
    }

    scwin.setReturnValue("[B] 지도 변경 : " + map_readonly.getCurrentMap());
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
